import subprocess, math

def pastel(fmt, col):
    r=subprocess.run(['./executable','-m','off','format',fmt,col], capture_output=True, text=True)
    return r.stdout.strip()

# Standard sRGB to XYZ D65
def srgb_to_linear(c):
    c=c/255.0
    if c <= 0.04045:
        return c/12.92
    else:
        return ((c+0.055)/1.055)**2.4

def rgb_to_xyz(r,g,b):
    R=srgb_to_linear(r); G=srgb_to_linear(g); B=srgb_to_linear(b)
    X = R*0.4124564 + G*0.3575761 + B*0.1804375
    Y = R*0.2126729 + G*0.7151522 + B*0.0721750
    Z = R*0.0193339 + G*0.1191920 + B*0.9503041
    return X,Y,Z

def xyz_to_lab(x,y,z):
    # D65 reference white
    Xn, Yn, Zn = 0.95047, 1.0, 1.08883
    def f(t):
        if t > 0.008856:
            return t**(1/3)
        else:
            return 7.787*t + 16/116
    fx=f(x/Xn); fy=f(y/Yn); fz=f(z/Zn)
    L=116*fy -16
    a=500*(fx-fy)
    b=200*(fy-fz)
    return L,a,b

for col, rgb in [('red',(255,0,0)),('blue',(0,0,255)),('lime',(0,255,0)),('white',(255,255,255)),('black',(0,0,0)),('#123456',(0x12,0x34,0x56))]:
    X,Y,Z=rgb_to_xyz(*rgb)
    L,a,b=xyz_to_lab(X,Y,Z)
    print(col, f"L={L:.2f} a={a:.2f} b={b:.2f} pastel {pastel('lab',col)} {pastel('lab-a',col)} {pastel('lab-b',col)}")
PY"}

