NAME_TO_HEX = {}
for n,h in NAMED_COLORS:
    NAME_TO_HEX[n]=h
    # grey aliases
    if "gray" in n:
        NAME_TO_HEX[n.replace("gray","grey")]=h
NAME_TO_HEX["cyan"]="#00ffff"
NAME_TO_HEX["magenta"]="#ff00ff"
# also ensure aqua/fuchsia already there
HEX_TO_RGB = {}
for n,h in NAMED_COLORS:
    r=int(h[1:3],16); g=int(h[3:5],16); b=int(h[5:7],16)
    HEX_TO_RGB[h.lower()]=(r,g,b)

# Precompute named RGB list for nearest search
NAMED_RGB_LIST = []
for n,h in NAMED_COLORS:
    r=int(h[1:3],16); g=int(h[3:5],16); b=int(h[5:7],16)
    NAMED_RGB_LIST.append((n,r,g,b))

class Color:
    def __init__(self,r,g,b,a=1.0):
        self.r=int(round(max(0,min(255,r))))
        self.g=int(round(max(0,min(255,g))))
        self.b=int(round(max(0,min(255,b))))
        self.a=float(a)
        if self.a<0: self.a=0
        if self.a>1: self.a=1
    def copy(self):
        return Color(self.r,self.g,self.b,self.a)
    def __eq__(self,other):
        return self.r==other.r and self.g==other.g and self.b==other.b

def clamp01(x):
    if x<0: return 0
    if x>1: return 1
    return x

def rgb_to_hsl(r,g,b):
    rf=r/255.0; gf=g/255.0; bf=b/255.0
    mx=max(rf,gf,bf); mn=min(rf,gf,bf)
    l=(mx+mn)/2.0
    if mx==mn:
        h=0.0; s=0.0
    else:
        d=mx-mn
        if l>0.5:
            s=d/(2.0-mx-mn)
        else:
            s=d/(mx+mn)
        if mx==rf:
            h=(gf-bf)/d + (6 if gf<bf else 0)
        elif mx==gf:
            h=(bf-rf)/d + 2
        else:
            h=(rf-gf)/d + 4
        h*=60.0
        # h in [0,360)
        h=h%360.0
        # Preserve 360? Caller handles? For conversion from RGB, hue 0 stays 0, not 360.
        # But if h is very close to 360 due to floating, keep?
    return (h,s,l)

def hsl_to_rgb(h,s,l):
    h=float(h); s=float(s); l=float(l)
    # normalize hue: pastel quirky: if h>360 or h<0 then modulo, else keep (so 360 stays 360)
    # For hsl_to_rgb, hue 360 and 0 are same, so normalize modulo for conversion
    # But we need to handle hue 360 as 0 for conversion
    h_norm = h % 360.0
    # Actually for conversion, 360%360=0, fine
    h_norm = h_norm % 360.0
    if h_norm<0:
        h_norm+=360.0
    s=clamp01(s); l=clamp01(l)
    if s==0:
        v=int(round(l*255))
        return (v,v,v)
    # standard
