# ---------- 256 palette for ansi ----------
_XTERM_LEVELS=[0,95,135,175,215,255]
_XTERM_PALETTE={}
for idx in range(16,232):
    i=idx-16
    r=_XTERM_LEVELS[(i//36)%6]; g=_XTERM_LEVELS[(i//6)%6]; b=_XTERM_LEVELS[i%6]
    _XTERM_PALETTE[idx]=(r,g,b)
for idx in range(232,256):
    v=8+10*(idx-232)
    _XTERM_PALETTE[idx]=(v,v,v)

def rgb_to_ansi8(r,g,b):
    # r,g,b 0-255 ints
    best=16; bestd=None
    for idx in range(16,256):
        pr,pg,pb=_XTERM_PALETTE[idx]
        d=(r-pr)*(r-pr)+(g-pg)*(g-pg)+(b-pb)*(b-pb)
        if bestd is None or d<bestd:
            bestd=d; best=idx
    return best

