        return ColorF(r2/255.0,g2/255.0,b2/255.0,c.a,None)
    elif p=="oklab-a":
        r,g,b=color_to_ints(c)
        L,a,bb=rgb_to_oklab(r,g,b)
        r2,g2,b2=oklab_to_rgb(L,v,bb)
        return ColorF(r2/255.0,g2/255.0,b2/255.0,c.a,None)
    elif p=="oklab-b":
        r,g,b=color_to_ints(c)
        L,a,bb=rgb_to_oklab(r,g,b)
        r2,g2,b2=oklab_to_rgb(L,a,v)
        return ColorF(r2/255.0,g2/255.0,b2/255.0,c.a,None)
    elif p=="red":
        # v is 0-255?
        r,g,b=color_to_ints(c)
        return ColorF(v/255.0,g/255.0,b/255.0,c.a,None)
    elif p=="green":
        r,g,b=color_to_ints(c)
        return ColorF(r/255.0,v/255.0,b/255.0,c.a,None)
    elif p=="blue":
        r,g,b=color_to_ints(c)
        return ColorF(r/255.0,g/255.0,v/255.0,c.a,None)
    elif p=="hsl-hue":
        h,s,l=get_hsl_from_colorF(c)
        h2_norm=normalize_hue_quirky(v)
        r,g,b=hsl_to_rgb_floats(h2_norm,s,l)
        return ColorF(r,g,b,c.a,h2_norm)
    elif p=="hsl-saturation":
        h,s,l=get_hsl_from_colorF(c)
        s2=max(0,min(1,v))
        r,g,b=hsl_to_rgb_floats(h,s2,l)
        return ColorF(r,g,b,c.a,h)
    elif p=="hsl-lightness":
        h,s,l=get_hsl_from_colorF(c)
        l2=max(0,min(1,v))
        r,g,b=hsl_to_rgb_floats(h,s,l2)
        return ColorF(r,g,b,c.a,h)
    elif p=="alpha":
        return ColorF(c.r,c.g,c.b,v,c.hue)
    else:
        return None

