import subprocess, sys, math
sys.path.insert(0,'/workspace')
import pastel
def orig(col):
    return subprocess.run(['./executable','-m','off','format','name',col], capture_output=True, text=True).stdout.strip()
def nearest(metric, r,g,b):
    best=None; bestd=None
    for n,rr,gg,bb in pastel.NAMED_RGB_LIST:
        if metric=="rgb":
            d=(r-rr)**2+(g-gg)**2+(b-bb)**2
        elif metric=="lab":
            L1,a1,b1=pastel.rgb_to_lab(r,g,b)
            L2,a2,b2=pastel.rgb_to_lab(rr,gg,bb)
            d=(L1-L2)**2+(a1-a2)**2+(b1-b2)**2
        elif metric=="lch":
            L1,C1,H1=pastel.rgb_to_lch(r,g,b)
            L2,C2,H2=pastel.rgb_to_lch(rr,gg,bb)
            # Hue circular? Use simple Euclidean in LCh with hue weighted? Or use Lab? For now Euclidean in L,C,H with hue circular distance?
            dh=min(abs(H1-H2),360-abs(H1-H2))
            d=(L1-L2)**2+(C1-C2)**2+(dh*0.5)**2
        elif metric=="oklab":
            L1,a1,b1=pastel.rgb_to_oklab(r,g,b)
            L2,a2,b2=pastel.rgb_to_oklab(rr,gg,bb)
            d=(L1-L2)**2+(a1-a2)**2+(b1-b2)**2
        else:
