{"command": "python3 <<'PY'
import subprocess, random
def o(args, inp=None):
    r=subprocess.run(['./executable']+args, input=inp, capture_output=True, text=True)
    return (r.stdout, r.stderr, r.returncode)
def n(args, inp=None):
    r=subprocess.run(['python3','/workspace/pastel.py']+args, input=inp, capture_output=True, text=True)
    return (r.stdout, r.stderr, r.returncode)
random.seed(1)
tests=[]
for _ in range(20):
    r=random.randint(0,255); g=random.randint(0,255); b=random.randint(0,255)
    col=f"#{r:02x}{g:02x}{b:02x}"
    for fmt in ['hex','rgb','hsl','cmyk','lab']:
        tests.append((['-m','off','format',fmt,col],None))
ok=0; fail=0
for args,inp in tests:
    ro=o(args,inp); rn=n(args,inp)
    if ro==rn:
        ok+=1
    else:
        fail+=1
        print(f"FAIL {args} {ro} {rn}")
print(f"ok {ok} fail {fail}")
PY"}

