    # For colorcheck/pick, compare lengths? For pick, stderr large, compare?
    if args[0] in ('colorcheck','pick'):
        # Compare stdout+stderr lengths? Actually pick stdout empty, stderr large, compare?
        match=(ro[0]==rn[0] and ro[1]==rn[1] and ro[2]==rn[2])
    else:
        match=(ro==rn)
    print(args, match)
